import * as vscode from 'vscode'
import * as cp from 'child_process'
import * as path from 'path'

function run(cmd: string): string {
  try {
    return cp.execSync(cmd, { timeout: 5000, stdio: ['pipe', 'pipe', 'pipe'] }).toString().trim()
  } catch {
    return ''
  }
}

function check(cmd: string): boolean {
  return run(cmd) !== ''
}

function buildEnvironmentReport(): string {
  const lines: string[] = []
  const now = new Date().toISOString()

  // --- OS ---
  const platform = process.platform
  const osName = platform === 'win32' ? 'Windows' : platform === 'darwin' ? 'macOS' : 'Linux'
  const arch = process.arch

  // --- Python ---
  const py3 = run('python3 --version 2>&1') || run('python --version 2>&1')
  const pyCmd = check('python3 --version 2>&1') ? 'python3' : check('python --version 2>&1') ? 'python' : ''
  const hasPy = pyCmd !== ''

  // --- PDF libraries ---
  const hasFitz = hasPy && check(`${pyCmd} -c "import fitz" 2>&1 && echo ok`)
  const fitzVer = hasFitz ? run(`${pyCmd} -c "import fitz; print(fitz.__version__)"`) : ''
  const hasPlumber = hasPy && check(`${pyCmd} -c "import pdfplumber" 2>&1 && echo ok`)
  const hasPdfminer = hasPy && check(`${pyCmd} -c "import pdfminer" 2>&1 && echo ok`)

  // --- Image libraries ---
  const hasPillow = hasPy && check(`${pyCmd} -c "from PIL import Image" 2>&1 && echo ok`)
  const pillowVer = hasPillow ? run(`${pyCmd} -c "from PIL import __version__; print(__version__)"`) : ''
  const hasCV2 = hasPy && check(`${pyCmd} -c "import cv2" 2>&1 && echo ok`)

  // --- CLI tools ---
  const hasPdftotext = check('pdftotext -v 2>&1 && echo ok') || check('pdftotext --help 2>&1 && echo ok')
  // poppler의 페이지 렌더러. PyMuPDF가 없는 기계에서 그림을 뽑는 실질적인 유일한 경로다
  const hasPdftoppm = check('pdftoppm -v 2>&1 && echo ok') || check('pdftoppm -h 2>&1 && echo ok')
  const hasConvert = check('convert --version 2>&1 && echo ok')
  const hasMagick = check('magick --version 2>&1 && echo ok')
  const hasGhostscript = check('gs --version 2>&1 && echo ok') || check('gswin64c --version 2>&1 && echo ok')

  const ok = (v: boolean | string) => v ? '✅' : '❌'

  lines.push(`# NodeGraph — Agent Environment Report`)
  lines.push(``)
  lines.push(`> Auto-generated by the NodeGraph extension at activation.`)
  lines.push(`> **AI agents: read this file to understand what tools are available on this machine.**`)
  lines.push(`> Re-generated each time a \`.nodegraph.json\` file is opened.`)
  lines.push(``)
  lines.push(`Generated: \`${now}\``)
  lines.push(``)
  lines.push(`---`)
  lines.push(``)
  lines.push(`## System`)
  lines.push(``)
  lines.push(`| | |`)
  lines.push(`|---|---|`)
  lines.push(`| OS | ${osName} (\`${platform}\`) |`)
  lines.push(`| Architecture | \`${arch}\` |`)
  lines.push(`| Python | ${hasPy ? `${ok(true)} \`${py3}\`` : `${ok(false)} not found`} |`)
  lines.push(`| Python command | ${hasPy ? `\`${pyCmd}\`` : 'N/A'} |`)
  lines.push(``)
  lines.push(`---`)
  lines.push(``)
  lines.push(`## PDF Reading Capabilities`)
  lines.push(``)
  lines.push(`| Tool | Available | Notes |`)
  lines.push(`|------|:---------:|-------|`)
  lines.push(`| PyMuPDF (\`fitz\`) | ${ok(hasFitz)} | ${hasFitz ? `v${fitzVer} — recommended` : 'Install: \`pip install pymupdf\`'} |`)
  lines.push(`| pdfplumber | ${ok(hasPlumber)} | ${hasPlumber ? 'available' : 'Install: \`pip install pdfplumber\`'} |`)
  lines.push(`| pdfminer | ${ok(hasPdfminer)} | ${hasPdfminer ? 'available' : 'Install: \`pip install pdfminer.six\`'} |`)
  lines.push(`| poppler (\`pdftotext\`) | ${ok(hasPdftotext)} | ${hasPdftotext ? 'CLI tool available' : platform === 'win32' ? 'Install: download poppler for Windows' : platform === 'darwin' ? 'Install: \`brew install poppler\`' : 'Install: \`apt install poppler-utils\`'} |`)
  lines.push(`| poppler (\`pdftoppm\`) | ${ok(hasPdftoppm)} | ${hasPdftoppm ? 'renders pages to PNG — the image-extraction path when PyMuPDF is missing' : platform === 'win32' ? 'Install: download poppler for Windows' : platform === 'darwin' ? 'Install: \`brew install poppler\`' : 'Install: \`apt install poppler-utils\`'} |`)
  lines.push(`| Ghostscript (\`gs\`) | ${ok(hasGhostscript)} | ${hasGhostscript ? 'available' : 'optional'} |`)
  lines.push(``)
  lines.push(`---`)
  lines.push(``)
  lines.push(`## Image Processing Capabilities`)
  lines.push(``)
  lines.push(`| Tool | Available | Notes |`)
  lines.push(`|------|:---------:|-------|`)
  lines.push(`| Pillow (\`PIL\`) | ${ok(hasPillow)} | ${hasPillow ? `v${pillowVer} — recommended` : 'Install: \`pip install Pillow\`'} |`)
  lines.push(`| OpenCV (\`cv2\`) | ${ok(hasCV2)} | ${hasCV2 ? 'available' : 'Install: \`pip install opencv-python\`'} |`)
  lines.push(`| ImageMagick (\`convert\`) | ${ok(hasConvert || hasMagick)} | ${(hasConvert || hasMagick) ? 'CLI tool available' : platform === 'win32' ? 'Install: imagemagick.org' : platform === 'darwin' ? 'Install: \`brew install imagemagick\`' : 'Install: \`apt install imagemagick\`'} |`)
  lines.push(``)
  lines.push(`---`)
  lines.push(``)
  lines.push(`## Agent Recommendations`)
  lines.push(``)

  if (!hasPy) {
    lines.push(`> ⚠️ **Python not found.** PDF reading and image processing via Python are not available.`)
    lines.push(`> Install Python from https://python.org, then reopen a \`.nodegraph.json\` file to re-run this check.`)
    lines.push(``)
  }

  lines.push(`### Reading a PDF`)
  if (hasFitz) {
    lines.push(`Use PyMuPDF (recommended — fastest and most accurate):`)
    lines.push(`\`\`\`python`)
    lines.push(`import fitz`)
    lines.push(`doc = fitz.open("paper.pdf")`)
    lines.push(`text = "\\n".join(page.get_text() for page in doc)`)
    lines.push(`\`\`\``)
  } else if (hasPlumber) {
    lines.push(`Use pdfplumber:`)
    lines.push(`\`\`\`python`)
    lines.push(`import pdfplumber`)
    lines.push(`with pdfplumber.open("paper.pdf") as pdf:`)
    lines.push(`    text = "\\n".join(p.extract_text() or "" for p in pdf.pages)`)
    lines.push(`\`\`\``)
  } else if (hasPdftotext) {
    lines.push(`Use poppler CLI:`)
    lines.push(`\`\`\`bash`)
    lines.push(`pdftotext paper.pdf -`)
    lines.push(`\`\`\``)
  } else {
    lines.push(`❌ No PDF reading tool available. Ask the user to install PyMuPDF: \`pip install pymupdf\``)
  }

  lines.push(``)
  lines.push(`### Extracting images from a PDF`)
  if (hasFitz) {
    lines.push(`\`\`\`python`)
    lines.push(`import fitz`)
    lines.push(`doc = fitz.open("paper.pdf")`)
    lines.push(`for i, page in enumerate(doc):`)
    lines.push(`    for img in page.get_images():`)
    lines.push(`        xref = img[0]`)
    lines.push(`        pix = fitz.Pixmap(doc, xref)`)
    lines.push(`        pix.save(f"fig_{i}_{xref}.png")`)
    lines.push(`\`\`\``)
  } else if (hasPdftoppm) {
    // PyMuPDF가 없을 때 막다른 길을 안내하지 않도록: poppler로 페이지를 이미지로 렌더한 뒤
    // (Pillow가 있으면) 필요한 그림만 잘라낸다. 실제로 이 경로로 그림 추출이 된다.
    lines.push(`PyMuPDF is not installed, so render the page with poppler and crop the figure out:`)
    lines.push(`\`\`\`bash`)
    lines.push(`pdftoppm -png -r 240 -f 5 -l 5 paper.pdf page   # → page-05.png (page 5 at 240 dpi)`)
    lines.push(`\`\`\``)
    if (hasPillow) {
      lines.push(`Then crop the figure with Pillow:`)
      lines.push(`\`\`\`python`)
      lines.push(`from PIL import Image`)
      lines.push(`img = Image.open("page-05.png")`)
      lines.push(`img.crop((left, top, right, bottom)).save("fig_01.png")   # pixels at 240 dpi`)
      lines.push(`\`\`\``)
    } else {
      lines.push(`Pillow is not installed either, so crop with ImageMagick (\`magick page-05.png -crop WxH+X+Y fig_01.png\`) or save whole pages.`)
    }
  } else if (hasPillow) {
    lines.push(`Pillow can crop images but cannot read a PDF. Install one of: \`pip install pymupdf\`, or poppler (\`apt install poppler-utils\` / \`brew install poppler\`) for \`pdftoppm\`.`)
  } else {
    lines.push(`❌ No image extraction tool available. Install \`pip install pymupdf\`, or poppler for \`pdftoppm\`.`)
  }

  lines.push(``)
  lines.push(`---`)
  lines.push(``)
  lines.push(`*To refresh this report, reopen any \`.nodegraph.json\` file.*`)

  return lines.join('\n')
}

// Writes ENVIRONMENT.md into one specific folder. Used both by the
// per-workspace-folder loop below (activation time) and by the
// "Copy Agent Spec to Workspace" command (extension.ts), which needs it
// written into the exact folder it targets — not necessarily a workspace
// root — so that folder ends up with both agent files together, consistent
// with what SPEC.md expects to find next to it.
//
// Everything NodeGraph writes into a workspace lives under a `nodegraph/`
// subfolder of .agent/.prompt — those top-level folders are shared territory
// (RTLGraph namespaces itself the same way, e.g. .agent/rtlgraph/), so tools
// don't collide when a project uses more than one of them.
export async function writeEnvironmentReportToFolder(folderUri: vscode.Uri): Promise<boolean> {
  const agentDir = vscode.Uri.joinPath(folderUri, '.agent', 'nodegraph')
  const outFile = vscode.Uri.joinPath(agentDir, 'ENVIRONMENT.md')
  try {
    await vscode.workspace.fs.createDirectory(agentDir)
    await vscode.workspace.fs.writeFile(outFile, Buffer.from(buildEnvironmentReport(), 'utf-8'))
    return true
  } catch {
    return false
  }
}

export async function writeEnvironmentReport(workspaceFolders: readonly vscode.WorkspaceFolder[]): Promise<void> {
  if (!workspaceFolders || workspaceFolders.length === 0) return
  for (const folder of workspaceFolders) {
    await writeEnvironmentReportToFolder(folder.uri)
  }
}

// SPEC.md (the NodeGraph agent spec) ships inside the extension bundle, not the user's workspace,
// so an AI agent operating on the workspace has no way to find it without being
// told the extension's install path. Unlike ENVIRONMENT.md (small, genuinely
// per-machine, fine to regenerate silently every activation), this is a large
// static doc identical across every install — copying it into every workspace
// folder automatically would mean it can land in repos the user never chose to
// touch. So this only runs when the user explicitly invokes the "NodeGraph:
// Copy Agent Spec to Workspace" command, targeting exactly one folder — the one
// resolved by resolveTargetFolder() in extension.ts (Explorer right-click target,
// or a folder picker in a multi-root workspace).
export async function syncAgentSpec(extensionUri: vscode.Uri, targetFolder: vscode.Uri): Promise<boolean> {
  const bundledSpec = vscode.Uri.joinPath(extensionUri, '.agent', 'nodegraph', 'SPEC.md')
  let content: Uint8Array
  try {
    content = await vscode.workspace.fs.readFile(bundledSpec)
  } catch {
    return false
  }

  const agentDir = vscode.Uri.joinPath(targetFolder, '.agent', 'nodegraph')
  const outFile = vscode.Uri.joinPath(agentDir, 'SPEC.md')
  try {
    await vscode.workspace.fs.createDirectory(agentDir)
    await vscode.workspace.fs.writeFile(outFile, content)
    return true
  } catch {
    return false
  }
}

// Same idea as syncAgentSpec, for the ready-to-paste example prompts
// (README's "Example prompt" section) instead of the schema doc — copied
// from the extension bundle's .prompt/ folder into the target workspace
// folder's own .prompt/, so a user (or an agent acting for them) can open
// {paper,lecture,code}/{korean,english}.md directly instead of copy-pasting
// out of the README.
export async function syncPromptTemplates(extensionUri: vscode.Uri, targetFolder: vscode.Uri): Promise<boolean> {
  const bundledDir = vscode.Uri.joinPath(extensionUri, '.prompt', 'nodegraph')
  const outDir = vscode.Uri.joinPath(targetFolder, '.prompt', 'nodegraph')
  try {
    for (const kind of ['paper', 'lecture', 'code']) {
      const kindOutDir = vscode.Uri.joinPath(outDir, kind)
      await vscode.workspace.fs.createDirectory(kindOutDir)
      // 파일명을 고정 목록으로 두면 프롬프트를 새로 추가해도(예: *-hierarchical.md)
      // 워크스페이스로 영영 복사되지 않는다 — 번들된 폴더를 그대로 읽어서 옮긴다
      const entries = await vscode.workspace.fs.readDirectory(vscode.Uri.joinPath(bundledDir, kind))
      for (const [name, type] of entries) {
        if (type !== vscode.FileType.File || !name.endsWith('.md')) continue
        const content = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(bundledDir, kind, name))
        await vscode.workspace.fs.writeFile(vscode.Uri.joinPath(kindOutDir, name), content)
      }
    }
    return true
  } catch {
    return false
  }
}
